-- Hosbah: an "app" recipe of the built-in catalog (internal/catalog), installed next to a site
-- (app) on the site's server. recipe_id + recipe_version name the recipe in the catalog both the
-- control plane and the agent embed; the image, limits, volumes and env of the container come from
-- there, never from this row or the wire. The container publishes its HTTP port on 127.0.0.1 only;
-- host_port is the ephemeral port Docker picked (null until the agent answered; a headless recipe
-- has none). proxy_host_id is the proxy host the install created, when the caller gave a hostname —
-- removed with the install. secrets is the JSON of the generated values, sealed with the team DEK and
-- bound to the install; no route returns it. env_injected is exactly what the install set on the
-- site, so a removal unsets those and nothing else. status: creating → ready | failed; removing
-- while recipe.remove runs. Rows go with their app.
ALTER TABLE app_installs ADD CONSTRAINT app_installs_name_check CHECK (name ~ '^[a-z][a-z0-9-]{0,30}$');
ALTER TABLE app_installs ADD CONSTRAINT app_installs_recipe_check CHECK (recipe_id ~ '^[a-z][a-z0-9-]{1,40}$');
ALTER TABLE app_installs ADD CONSTRAINT app_installs_host_port_check CHECK (host_port IS NULL OR host_port BETWEEN 1 AND 65535);
ALTER TABLE app_installs ADD CONSTRAINT app_installs_status_check CHECK (status IN ('creating', 'ready', 'failed', 'removing'));
CREATE UNIQUE INDEX app_installs_app_name_key ON app_installs (app_id, name);
CREATE UNIQUE INDEX app_installs_id_team_key ON app_installs (id, team_id);
CREATE INDEX app_installs_team_idx ON app_installs (team_id);
CREATE INDEX app_installs_app_idx ON app_installs (app_id);
CREATE INDEX app_installs_server_idx ON app_installs (server_id);
